// audit-report.test.mjs - audit-report.mjs report: REPORT.md, FINDINGS-DETAIL.md and NEEDS-VALIDATION.md generated by code from the JSON, checked against golden files made from
// fixed fixtures (UPDATE_GOLDEN=1 rewrites them, and the diff is reviewed), and by what must always hold: a zero-confirmed report says so and invents nothing, an incomplete run
// lists its unresolved candidates first, every ledger status is counted on its own, no needs_validation row has a severity, prose follows the JSON, hostile text stays inside its
// line, and the command refuses to derive prose from records a vendored validator rejects. Every fixture passes both vendored validators.
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from '../../../scripts/workflow-harness.mjs'
import { REPORT_FILES, buildReports, reportContext, writeReport } from '../skills/security-audit/audit-report.mjs'
import { markIncomplete, STATUSES } from '../skills/security-audit/audit-run.mjs'
import { audit, ENV, meta, sh } from './audit-fixtures.mjs'
import { DECISIONS, META, NV, RJ, CF, STATE, UNIT, fixtureRun } from './report-fixtures.mjs'
import { atVerify, next, passed, verifyRound } from './verdict-fixtures.mjs'
import { listFiles } from './audit-fixtures.mjs'

const GOLDEN = join(dirname(fileURLToPath(import.meta.url)), 'golden')
const VALIDATORS = { findings: 'PASS: 3 findings valid', ledger: 'PASS: 7 coverage units valid' }
const SEV = { critical: 'critical', high: 'high', medium: 'medium', low: 'low' }
const sev = (fp, level, over = {}) => CF(fp, { severity: { likelihood: { score: level, reason: `Likelihood ${level}.` }, impact: { score: level, reason: `Impact ${level}.` }, overall_severity: level }, ...over })
const golden = (name, text) => {
  const file = join(GOLDEN, name)
  if (process.env.UPDATE_GOLDEN) { writeFileSync(file, text); return }
  assert.ok(existsSync(file), `${name} is missing: UPDATE_GOLDEN=1 writes it`)
  const want = readFileSync(file, 'utf8')
  if (want !== text) {
    const a = want.split('\n'), b = text.split('\n')
    const i = a.findIndex((l, k) => l !== b[k])
    assert.fail(`${name} differs at line ${i + 1}:\n  golden:    ${JSON.stringify(a[i])}\n  generated: ${JSON.stringify(b[i])}`)
  }
}
const reports = (dir, validators = VALIDATORS) => buildReports(reportContext(dir), validators)

// ---- the fixed scenarios ----
const LEDGER_MIXED = () => [
  UNIT('a', 'candidate', { result_fingerprints: ['fp-a'], hardening: ['Rate limits are absent on login.'], priority_class: 1 }), UNIT('b', 'candidate', { result_fingerprints: ['fp-b'], priority_class: 3 }),
  UNIT('c', 'covered'), UNIT('d', 'blocked'), UNIT('e', 'deferred'), UNIT('f', 'not_applicable'), UNIT('g', 'out_of_scope'),
]
const CRITIC_DONE = { missing_units: [], reassign_ids: [], resolved_prior_leads: [], stop: true }
const zeroConfirmed = () => fixtureRun({ ledger: LEDGER_MIXED(), findings: [NV('fp-a', { title: 'Unchecked owner on update' }), NV('fp-b', { title: 'Another lead', validation_plan: { local: 'Run it locally.', deployment: 'Ask the owner.' } }), RJ('fp-r')], critic: CRITIC_DONE })
const incomplete = () => fixtureRun({
  meta: META({ run_status: 'incomplete', incomplete_reason: 'validation_budget_exhausted', budget: 40, agents_spent: 41 }), state: STATE({ last: 'verify' }),
  ledger: [UNIT('a', 'candidate', { result_fingerprints: ['fp-a'] }), UNIT('u', 'candidate', { result_fingerprints: ['fp-u'], unresolved: ['validation_budget_exhausted'] }), UNIT('c', 'covered')],
  findings: [NV('fp-a', { title: 'The one lead that was verified' })],
  pool: [{ fingerprint: 'fp-a', proposed_verdict: 'needs_validation', hunter_ids: ['h1-01'], units: [], record: {} }, { fingerprint: 'fp-u', proposed_verdict: 'needs_validation', hunter_ids: ['h1-02'], units: [], record: {} }],
  decisions: DECISIONS([{ fingerprint: 'fp-a', n: 1, record: NV('fp-a'), decision: 'needs_validation', verifier_id: 'v01' }, { fingerprint: 'fp-u', n: 2, state: 'unvalidated', unresolved: 'validation_budget_exhausted' }]), critic: CRITIC_DONE,
})
const confirmed = () => fixtureRun({
  ledger: [UNIT('hi', 'candidate', { result_fingerprints: ['fp-hi'] }), UNIT('mid', 'candidate', { result_fingerprints: ['fp-mid'] }), UNIT('lo', 'candidate', { result_fingerprints: ['fp-lo'] }), UNIT('nv', 'candidate', { result_fingerprints: ['fp-nv'] })],
  findings: [sev('fp-hi', 'high', { title: 'High finding', remediation: { strategy: 'Check ownership first.', code_changes: [{ file_name: 'src/app.js', fixed_code: 'if (note.owner !== user.id) throw new Error("forbidden")\n```\nreturn note' }] } }), sev('fp-mid', 'medium', { title: 'Medium finding' }), sev('fp-lo', 'low', { title: 'Low finding' }), NV('fp-nv', { title: 'A lead' }), RJ('fp-rj')], critic: CRITIC_DONE,
})
const early = () => fixtureRun({ meta: META({ run_status: 'incomplete', incomplete_reason: 'budget_cannot_fund_reconnaissance_and_reserves', budget: 3, agents_spent: 0 }), state: STATE({ last: 'init', wave: 0, critic_kind: null }) })

console.log('== golden reports')
await test('a complete run with no confirmed finding: the three files are the golden files', () => {
  const r = reports(zeroConfirmed())
  assert.deepEqual(Object.keys(r), REPORT_FILES)
  for (const [name, text] of Object.entries(r)) golden(`zero-confirmed.${name}`, text)
})
await test('an incomplete run with an unvalidated candidate: the three files are the golden files', () => {
  for (const [name, text] of Object.entries(reports(incomplete(), { findings: 'PASS: 1 findings valid', ledger: 'PASS: 3 coverage units valid' }))) golden(`incomplete-unresolved.${name}`, text)
})
await test('a synthetic confirmed high, medium and low finding beside a lead and a rejection: the three files are the golden files', () => {
  for (const [name, text] of Object.entries(reports(confirmed(), { findings: 'PASS: 5 findings valid', ledger: 'PASS: 4 coverage units valid' }))) golden(`confirmed.${name}`, text)
})
await test('a run that stopped before any ledger or finding: the three files are the golden files, and say that no coverage claim is made', () => {
  const r = reports(early(), { findings: null, ledger: null })
  for (const [name, text] of Object.entries(r)) golden(`early-incomplete.${name}`, text)
  assert.match(r['REPORT.md'], /No coverage ledger was written: no coverage claim is made\./)
  assert.match(r['REPORT.md'], /the budget could not fund reconnaissance and the reserves, so no audit pass ran/)
})

console.log('== what a report must always do')
await test('a zero-confirmed report says so and invents nothing: no confirmed table, no severity word in a lead\'s row, no finding of any level', () => {
  const text = reports(zeroConfirmed())['REPORT.md']
  const confirmedSection = text.slice(text.indexOf('## Confirmed findings'), text.indexOf('## NEEDS VALIDATION'))
  assert.match(confirmedSection, /^## Confirmed findings\n\nNone\./)
  assert.ok(!confirmedSection.includes('| Severity |'), 'no table')
  assert.match(text, /No confirmed vulnerability is reported: a confirmation needs a bounded observed result from running target code, and this audit executes none\./)
  const needs = text.slice(text.indexOf('## NEEDS VALIDATION'), text.indexOf('## Hardening notes'))
  assert.ok(!/critical|\bhigh\b|medium|\blow\b|informational/i.test(needs), 'a lead has no severity')
  assert.ok(!/\bLOW\b/.test(text), 'no invented LOW finding')
  assert.match(text, /not a clean bill of health/)
})
await test('an incomplete run lists every unresolved candidate first, before the run details, and does not describe it as a finding', () => {
  const text = reports(incomplete())['REPORT.md']
  const at = s => text.indexOf(s)
  assert.ok(at('## Status') < at('### Unresolved candidates') && at('### Unresolved candidates') < at('## Run'), 'status and the unresolved list come first')
  assert.match(text, /\*\*INCOMPLETE\*\* \(`validation_budget_exhausted`\): a candidate or a record could not be given an independent verifier/)
  assert.match(text, /\| `fp-u` \| `validation_budget_exhausted` \| Route u \(Boundary of u\) \|/)
  assert.match(text, /none is a finding under any verdict, and none is in findings\.json/)
  assert.ok(!text.slice(at('## NEEDS VALIDATION')).includes('fp-u'.replace('fp-u', 'The unvalidated')), 'it is not among the leads')
  assert.ok(!reports(incomplete())['NEEDS-VALIDATION.md'].split('## The one lead')[0].includes('fp-u') === false, 'NEEDS-VALIDATION.md names it before the leads, as unresolved')
  assert.match(reports(incomplete())['NEEDS-VALIDATION.md'], /## Unresolved candidates \(not findings\)\n\n- `fp-u`: `validation_budget_exhausted`/)
  assert.match(text, /\*\*This is a partial pass:\*\* the run is incomplete; it ran under a strict budget of 40 agent invocations\./)
})
await test('every ledger status is counted on its own, all eight, and the total is the ledger\'s', () => {
  const text = reports(zeroConfirmed())['REPORT.md']
  const table = Object.fromEntries([...text.matchAll(/^\| (\w+) \| (\d+) \|$/gm)].map(m => [m[1], Number(m[2])]))
  assert.deepEqual(table, { planned: 0, not_applicable: 1, out_of_scope: 1, in_progress: 0, covered: 1, candidate: 2, blocked: 1, deferred: 1 })
  assert.deepEqual(Object.keys(table), STATUSES)
  assert.match(text, /\| \*\*total\*\* \| 7 \|/)
  assert.match(text, /a blocked unit is not covered, and a deferred one is not reviewed/)
})
await test('the report follows the JSON: a verdict changed in findings.json moves the record between the confirmed and the needs-validation sections, and a title or a count changes with it', () => {
  const lead = fixtureRun({ ledger: [UNIT('a', 'candidate', { result_fingerprints: ['fp-a'] })], findings: [NV('fp-a', { title: 'TITLE-ONE' })], critic: CRITIC_DONE })
  const conf = fixtureRun({ ledger: [UNIT('a', 'candidate', { result_fingerprints: ['fp-a'] })], findings: [sev('fp-a', 'high', { title: 'TITLE-ONE' })], critic: CRITIC_DONE })
  const a = reports(lead)['REPORT.md'], b = reports(conf)['REPORT.md']
  const part = (t, from, to) => t.slice(t.indexOf(from), t.indexOf(to))
  assert.ok(part(a, '## NEEDS VALIDATION', '## Hardening').includes('TITLE-ONE') && !part(a, '## Confirmed findings', '## NEEDS VALIDATION').includes('TITLE-ONE'))
  assert.ok(!part(b, '## NEEDS VALIDATION', '## Hardening').includes('TITLE-ONE') && part(b, '## Confirmed findings', '## NEEDS VALIDATION').includes('TITLE-ONE'))
  assert.match(a, /1 lead needs validation/)
  assert.match(b, /1 confirmed vulnerability reported\./)
  assert.match(reports(conf)['FINDINGS-DETAIL.md'], /## TITLE-ONE/)
  assert.ok(!reports(lead)['FINDINGS-DETAIL.md'].includes('TITLE-ONE'))
})
await test('FINDINGS-DETAIL.md has exactly the confirmed medium, high and critical records, in severity order, with the source path and the reproduction; never a low one, a lead or a rejection', () => {
  const r = reports(confirmed())
  const detail = r['FINDINGS-DETAIL.md']
  assert.deepEqual([...detail.matchAll(/^## (.*)$/gm)].map(m => m[1]), ['High finding', 'Medium finding'])
  for (const never of ['Low finding', 'A lead', 'fp-rj', 'fp-nv', 'fp-lo']) assert.ok(!detail.includes(never), never)
  for (const need of ['### Source path', '### Evidence', '### Reproduction', 'Dummy principal:', 'Observed result:', 'Security invariant:', '### Conditions', '### Source-level remediation', 'Regression case:']) assert.ok(detail.includes(need), need)
  assert.match(detail, /Suggested code changes\. These are the audit's suggestions: they were not applied and not reviewed\.\n\n- `src\/app\.js`\n\n````text\nif \(note\.owner !== user\.id\)/, 'code_changes are suggestions, in a fence the code inside cannot close')
  assert.equal(detail.split('Suggested code changes').length - 1, 1, 'only the finding that has them')
  const table = r['REPORT.md'].slice(r['REPORT.md'].indexOf('| Severity |'))
  assert.deepEqual([...table.matchAll(/^\| (high|medium|low) \| ([^|]*) \|/gm)].map(m => [m[1], m[2]]), [['high', 'High finding'], ['medium', 'Medium finding'], ['low', 'Low finding']], 'the confirmed table lists all three, most severe first')
})
await test('a lead appears with its trace, blocker and both plans and no severity, in NEEDS-VALIDATION.md and in the table, ordered by the priority of the coverage that found it', () => {
  const dir = fixtureRun({ ledger: [UNIT('late', 'candidate', { result_fingerprints: ['fp-aaa'], priority_class: 4 }), UNIT('early', 'candidate', { result_fingerprints: ['fp-zzz'], priority_class: 1 })], findings: [NV('fp-aaa', { title: 'Late lead' }), NV('fp-zzz', { title: 'Early lead' })], critic: CRITIC_DONE })
  const r = reports(dir)
  assert.deepEqual([...r['REPORT.md'].matchAll(/^\| (Early|Late) lead/gm)].map(m => m[1]), ['Early', 'Late'], 'priority 1 before priority 4 though fp-zzz sorts last')
  assert.deepEqual([...r['NEEDS-VALIDATION.md'].matchAll(/^## (.*)$/gm)].map(m => m[1]), ['Early lead', 'Late lead'])
  assert.ok(!/severity/i.test(r['NEEDS-VALIDATION.md'].replace('no severity', '')), 'no severity anywhere in the leads file')
})
await test('the prior-run use is counted from the ledger and the earlier runs: carried same-source confirmations, changed-source revalidations, carried leads', () => {
  const dir = fixtureRun({
    ledger: [{ ...UNIT('a', 'planned'), prior_status: 'prior_confirmed_same_source' }, { ...UNIT('b', 'planned'), prior_status: 'prior_confirmed_same_source' }, { ...UNIT('c', 'planned'), prior_status: 'prior_confirmed_changed_source' }, { ...UNIT('d', 'planned'), prior_status: 'prior_needs_validation' }],
    priors: [{ run_id: 'run-1', compatible: true }, { run_id: 'run-2', compatible: false }, { run_id: 'run-3', compatible: true }], critic: CRITIC_DONE,
  })
  const text = reports(dir)['REPORT.md']
  assert.match(text, /- Earlier runs: 3 found, 2 compatible\. Carried same-source confirmations: 2\. Changed-source revalidations: 1\. Carried needs-validation leads: 1\./)
  assert.ok(!text.includes('  - `'), 'no lead is named when the ledger names none')
  const named = fixtureRun({
    ledger: [{ ...UNIT('a', 'planned'), prior_status: 'prior_confirmed_same_source', prior_leads: [{ fingerprint: 'fp-same', verdict: 'confirmed', carried: true }] }, { ...UNIT('c', 'planned'), prior_status: 'prior_confirmed_changed_source', prior_leads: [{ fingerprint: 'fp-changed', verdict: 'confirmed', carried: false }] },
      { ...UNIT('d', 'planned'), prior_status: 'prior_needs_validation', prior_leads: [{ fingerprint: 'fp-lead', verdict: 'needs_validation', carried: true }] }, { ...UNIT('e', 'covered'), prior_status: 'prior_covered_same_source', prior_leads: [{ fingerprint: 'fp-not-named', verdict: 'rejected', carried: false }] }], critic: CRITIC_DONE })
  const lines = reports(named)['REPORT.md'].split('\n').filter(l => l.startsWith('  - `fp-'))
  assert.deepEqual(lines, ['  - `fp-changed`: changed-source revalidation (hunted again, not carried)', '  - `fp-lead`: carried needs-validation lead', '  - `fp-same`: carried same-source confirmation'])
})
await test('scope, a dirty tree and a strict budget are stated, and an unscoped complete run under no budget says none of them', () => {
  const scoped = fixtureRun({ meta: META({ scope_paths: ['src/app.js'], budget: 100, source_ref: { commit: 'c'.repeat(40), tree: 'd'.repeat(40), dirty: true, uncommitted: { tracked: 2, untracked: 1 } }, agents_spent: 12, agents_planned: 30 }), ledger: [UNIT('a')], critic: CRITIC_DONE })
  const text = reports(scoped)['REPORT.md']
  assert.match(text, /scope `src\/app\.js`/)
  assert.match(text, /Uncommitted changes in the working tree \(2 tracked, 1 untracked\) were not audited\./)
  assert.match(text, /Agents: 12 invoked of a budget of 100, 30 planned\./)
  assert.match(text, /\*\*This is a partial pass:\*\* it was scoped to `src\/app\.js`; it ran under a strict budget of 100 agent invocations\./)
  const quick = reports(fixtureRun({ meta: META({ profile: 'quick' }), ledger: [UNIT('a')], critic: CRITIC_DONE }))['REPORT.md']
  assert.match(quick, /\*\*This is a partial pass:\*\* the quick profile does not run the full method\./, 'a profile other than standard is a partial pass')
  const plain = reports(fixtureRun({ ledger: [UNIT('a')], critic: CRITIC_DONE }))['REPORT.md']
  assert.ok(!plain.includes('partial pass') && !plain.includes('Uncommitted') && plain.includes('(no budget set)'))
})
await test('a critic the budget could not fund is named: no clean-coverage claim, and the last critic that did run is not described as the final one', () => {
  const dir = fixtureRun({ meta: META({ run_status: 'incomplete', incomplete_reason: 'critic_budget_exhausted' }), state: STATE({ last: 'apply-critic', critic_kind: 'post-wave' }), ledger: [UNIT('a', 'covered'), UNIT('b', 'deferred')], critic: CRITIC_DONE })
  const text = reports(dir)['REPORT.md']
  assert.match(text, /The final-clean critic did not run: the budget no longer covered it\. No clean-coverage claim is made\./)
  const other = reports(fixtureRun({ state: STATE({ critic_kind: 'post-wave' }), ledger: [UNIT('a')], critic: CRITIC_DONE }))['REPORT.md']
  assert.match(other, /The last critic was the post-wave critic of wave 2: .* It was not the final-clean critic: coverage is not claimed to be clean\./)
  assert.match(reports(fixtureRun({ state: STATE({ critic_kind: null, wave: 0 }), ledger: [UNIT('a')] }))['REPORT.md'], /No coverage critic ran\./)
})

console.log('== hostile text stays inside its line')
const HOSTILE = '</details>\n\n# ALL CLEAR\n| x | y |\n|---|---|\n[click](http://evil.example) <img src=x onerror=1> ``` `tick` **bold**'
await test('titles, blockers, plans, trace descriptions, hardening notes and labels from the audited repository cannot open a heading, add a table row, forge a link or a tag, or leave their line', () => {
  const dir = fixtureRun({
    ledger: [UNIT('a', 'candidate', { result_fingerprints: ['fp-a'], surface: HOSTILE, boundary: HOSTILE, hardening: [HOSTILE] }), UNIT('d', 'deferred', { surface: HOSTILE, unresolved: [HOSTILE] })],
    findings: [NV('fp-a', { title: HOSTILE, blockers: [HOSTILE], validation_plan: { local: HOSTILE, deployment: HOSTILE }, trace: [{ kind: 'sink', file: 'src/app.js', line: 1, scope: HOSTILE, description: HOSTILE }], evidence: [{ file: 'src/app.js', line: 1, description: HOSTILE }] })],
    critic: CRITIC_DONE,
  })
  for (const [name, text] of Object.entries(reports(dir))) {
    const lines = text.split('\n')
    assert.ok(!lines.some(l => /^\s*(#+\s*ALL CLEAR|<\/details>|\[click\]|\| x \| y \|)/.test(l)), `${name}: no line of hostile text became a heading, a row or a tag of its own`)
    const own = lines.filter(l => /^#{1,6} /.test(l) && l.includes('ALL CLEAR'))
    assert.ok(own.every(l => l.startsWith('## ') && l.includes('&lt;/details&gt;') && !l.includes('\n')), `${name}: the title is the content of its own heading line, escaped`)
    assert.ok(!text.includes('](http://evil.example)') || text.includes('\\](http://evil.example)'), `${name}: the link is escaped`)
    assert.ok(!text.includes('<img') && !text.includes('</details>'), `${name}: no raw HTML`)
    for (const row of text.split('\n').filter(l => l.startsWith('| ') && !l.startsWith('| Status') && !l.startsWith('| Lead') && !l.startsWith('| Fingerprint') && !l.startsWith('| Severity'))) {
      const cols = row.replace(/\\\|/g, '').split('|').length - 2
      assert.ok(cols === 2 || cols === 3 || cols === 4 || cols === 5, `${name}: a row has a column count the table gave it: ${row.slice(0, 80)}`)
    }
  }
  const lead = reports(dir)['REPORT.md'].split('\n').find(l => l.startsWith('| \\&lt;') || l.startsWith('| &lt;'))
  assert.ok(lead && lead.split('|').length - 1 - (lead.match(/\\\|/g) ?? []).length === 6, 'the lead is one row of five cells')
})
await test('a report from hostile findings is still the same bytes when generated twice, and no file path or run directory appears in it', () => {
  const dir = zeroConfirmed()
  const a = reports(dir), b = reports(dir)
  assert.deepEqual(a, b)
  for (const text of Object.values(a)) assert.ok(!text.includes(dir) && !text.includes('/fixture/target') && !/\/tmp\//.test(text), 'no absolute path')
})

console.log('== the report command')
const lsRun = dir => readdirSync(dir).filter(f => !['tree'].includes(f)).sort()
await test('report writes the three files, saves the step, and next says done; a complete run stays complete', async () => {
  const dir = fixtureRun({ ledger: LEDGER_MIXED(), findings: [NV('fp-a'), NV('fp-b'), RJ('fp-r')], critic: CRITIC_DONE })
  const out = writeReport(dir)
  assert.equal(out.summary, 'report status=complete confirmed=0 needs_validation=2 rejected=1 unresolved=0')
  assert.deepEqual(REPORT_FILES.filter(f => !existsSync(join(dir, f))), [])
  assert.match(readFileSync(join(dir, 'REPORT.md'), 'utf8'), /findings\.json: PASS: 3 findings valid; coverage-ledger\.json: PASS: 7 coverage units valid/)
  assert.equal(next(dir), 'NEXT: done status=complete')
  assert.ok(!lsRun(dir).some(f => f.endsWith('.tmp')))
  assert.deepEqual(readFileSync(join(dir, 'REPORT.md'), 'utf8'), reports(dir, { findings: 'PASS: 3 findings valid', ledger: 'PASS: 7 coverage units valid' })['REPORT.md'])
  assert.throws(() => writeReport(dir), /report is not the next step of this run: NEXT: done status=complete/)
})
await test('a real pipeline run, validated and verified, is reported: complete, both validators pass, the files are the run\'s own and nothing is written into the audited repository', async () => {
  const run = await atVerify([{ name: 'a', candidates: ['fp-a'] }, { name: 'b', candidates: ['fp-b'] }])
  const res = await verifyRound(run.runDir, (l, item) => passed(item))
  assert.equal(res.apply.status, 0, res.apply.stdout)
  assert.equal(next(run.runDir), 'NEXT: report run=helper')
  const before = sh(run.repo, 'status', '--porcelain', '--ignored')
  const out = spawnSync(process.execPath, [join(dirname(fileURLToPath(import.meta.url)), '..', 'skills', 'security-audit', 'audit-report.mjs'), 'report', run.runDir], { encoding: 'utf8', env: { ...process.env, ...ENV } })
  assert.equal(out.status, 0, out.stdout + out.stderr)
  assert.match(out.stdout.trim().split('\n').at(-1), /^AUDIT: OK report status=complete confirmed=0 needs_validation=2 rejected=0 unresolved=0$/)
  assert.equal(next(run.runDir), 'NEXT: done status=complete')
  assert.equal(audit(['check', run.runDir]).last, `AUDIT: OK ${run.runDir} passes check`)
  assert.equal(sh(run.repo, 'status', '--porcelain', '--ignored'), before, 'the audited repository is untouched')
  const text = readFileSync(join(run.runDir, 'REPORT.md'), 'utf8')
  assert.ok(text.includes('2 leads need validation') && text.includes('Lead fp-a') && !text.includes(run.runDir))
})
await test('an incomplete real run is reported with its reason and its unresolved candidate first', async () => {
  const run = await atVerify([{ name: 'a', candidates: ['fp-a'] }, { name: 'b', candidates: ['fp-b'] }])
  markIncomplete(run.runDir, 'critic_budget_exhausted')
  assert.equal((await verifyRound(run.runDir, (l, item) => (item.fingerprint === 'fp-a' ? passed(item) : null))).apply.status, 0)
  assert.equal((await verifyRound(run.runDir, () => null)).apply.status, 0)
  assert.match(next(run.runDir), /^NEXT: report run=helper reason=critic_budget_exhausted$/)
  writeReport(run.runDir)
  const text = readFileSync(join(run.runDir, 'REPORT.md'), 'utf8')
  assert.ok(text.indexOf('### Unresolved candidates') > 0 && text.indexOf('### Unresolved candidates') < text.indexOf('## Run'))
  assert.match(text, /\*\*INCOMPLETE\*\* \(`critic_budget_exhausted`\)/)
  assert.match(text, /\| `fp-b` \| `record_verification_unresolved` \|/)
  assert.match(text, /The final-clean critic did not run/)
  assert.equal(next(run.runDir), 'NEXT: done status=incomplete reason=critic_budget_exhausted')
})
await test('a run still in progress when the report is asked for is decided first: complete-check marks it incomplete (complete_check_failed) and the report says so', () => {
  const dir = fixtureRun({ meta: META({ run_status: 'in_progress' }), ledger: [UNIT('a', 'candidate', { result_fingerprints: ['fp-a'] })], findings: [NV('fp-a')], critic: CRITIC_DONE })
  const out = writeReport(dir)
  assert.match(out.notes[0], /problem\(s\): the run is marked incomplete \(complete_check_failed\)/)
  assert.equal(meta(dir).run_status, 'incomplete')
  assert.match(readFileSync(join(dir, 'REPORT.md'), 'utf8'), /\*\*INCOMPLETE\*\* \(`complete_check_failed`\): complete-check found the run not completable/)
  assert.equal(next(dir), 'NEXT: done status=incomplete reason=complete_check_failed')
})
await test('report writes nothing when it is not the next step, or when findings.json or the ledger is there and a vendored validator rejects it', () => {
  const early = fixtureRun({ meta: META(), state: STATE({ last: 'validate' }), ledger: [UNIT('a')] })
  assert.throws(() => writeReport(early), /report is not the next step of this run: NEXT: write-findings/)
  assert.deepEqual(REPORT_FILES.filter(f => existsSync(join(early, f))), [])
  const bad = fixtureRun({ ledger: [UNIT('a')], findings: [NV('fp-a')], critic: CRITIC_DONE })
  writeFileSync(join(bad, 'findings.json'), JSON.stringify([{ verdict: 'confirmed', fingerprint: 'x' }]))
  assert.throws(() => writeReport(bad), /upstream's validator did not pass .*findings\.json \(FAIL: \d+ validation error\(s\)\): prose is never derived from records it rejects/)
  assert.deepEqual(REPORT_FILES.filter(f => existsSync(join(bad, f))), [])
  assert.equal(next(bad), 'NEXT: done status=complete'.replace('done status=complete', 'report run=helper'), 'the step is not saved')
  const badLedger = fixtureRun({ ledger: [UNIT('a')], findings: [], critic: CRITIC_DONE })
  const l = JSON.parse(readFileSync(join(badLedger, 'coverage-ledger.json'), 'utf8')); l[0].coverage_id = 'tampered'
  writeFileSync(join(badLedger, 'coverage-ledger.json'), JSON.stringify(l))
  assert.throws(() => writeReport(badLedger), /did not pass .*coverage-ledger\.json/)
  assert.deepEqual(REPORT_FILES.filter(f => existsSync(join(badLedger, f))), [])
  for (const content of ['{', '"x"', '{}', 'null', '7']) {
    writeFileSync(join(bad, 'findings.json'), content)
    assert.throws(() => writeReport(bad), /./, content)
  }
})
await test('a run that stopped before the ledger is reported from its metadata alone', () => {
  const dir = early()
  const out = writeReport(dir)
  assert.equal(out.summary, 'report status=incomplete confirmed=0 needs_validation=0 rejected=0 unresolved=0')
  assert.ok(!existsSync(join(dir, 'findings.json')) && !existsSync(join(dir, 'coverage-ledger.json')), 'the report does not invent either file')
  assert.equal(next(dir), 'NEXT: done status=incomplete reason=budget_cannot_fund_reconnaissance_and_reserves')
  assert.ok(listFiles(dir).filter(f => !f.startsWith('tree/')).includes('REPORT.md'))
})
